private Map<String, Object> pingOss(Instance instance) {
    Map<String, Object> result = new HashMap<>();
    String host = instance.getHost();
    if (host == null || host.trim().isEmpty()) {
        result.put("reachable", false);
        result.put("latencyMs", null);
        result.put("detail", "主机地址为空，无法进行OSS连接测试");
        return result;
    }
    String base = host.trim();
    if (!base.startsWith("http://") && !base.startsWith("https://")) {
        base = "http://" + base;
    }
    String resource = instance.getSchemaName() == null ? "" : instance.getSchemaName();
    // strip leading slash
    while (resource.startsWith("/")) resource = resource.substring(1);
    String urlStr = base;
    while (urlStr.endsWith("/")) urlStr = urlStr.substring(0, urlStr.length() - 1);
    if (!resource.isEmpty()) {
        urlStr = urlStr + "/" + resource;
    }
    long start = System.currentTimeMillis();
    HttpURLConnection connection = null;
    try {
        URL url = new URL(urlStr);
        connection = (HttpURLConnection) url.openConnection();
        connection.setConnectTimeout(5000);
        connection.setReadTimeout(5000);
        connection.setRequestMethod("GET");
        connection.setInstanceFollowRedirects(false);
        int code = connection.getResponseCode();
        long latency = System.currentTimeMillis() - start;
        result.put("reachable", true);
        result.put("latencyMs", latency);
        result.put("detail", "连接成功，状态码: " + code);
    } catch (IOException e) {
        result.put("reachable", false);
        result.put("latencyMs", null);
        result.put("detail", "连接超时");
    } finally {
        if (connection != null) connection.disconnect();
    }
    return result;
}
```

